# AI PICO â€” GUI Installer (source bundled, no GitHub fetch)
# (c) Dr Raouf Roshdy 2026
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$AppDir  = "$env:LOCALAPPDATA\AIPICO"
$Port    = 3456
$ServerUrl = "http://localhost:$Port"
$LogFile = "$AppDir\install.log"
$DisclaimerFile = "$AppDir\.disclaimer-accepted"
$sourceB64 = @"

@

if (-not (Test-Path $AppDir)) { New-Item -ItemType Directory -Path $AppDir -Force | Out-Null }

function Find-Node {
  $cmd = Get-Command node.exe -ErrorAction SilentlyContinue
  if ($cmd) { return $cmd.Source }
  foreach ($p in @("$env:ProgramFiles\nodejs\node.exe", "${env:ProgramFiles(x86)}\nodejs\node.exe", "$env:LOCALAPPDATA\Programs\nodejs\node.exe")) {
    if (Test-Path $p) { return $p }
  }
  return $null
}
function Find-Npm {
  $node = Find-Node
  if ($node) { $npm = Join-Path (Split-Path $node) "npm.cmd"; if (Test-Path $npm) { return $npm } }
  $cmd = Get-Command npm.cmd -ErrorAction SilentlyContinue
  if ($cmd) { return $cmd.Source }
  return $null
}

# ---------- Disclaimer (first run) ----------
if (-not (Test-Path $DisclaimerFile)) {
  $df = New-Object System.Windows.Forms.Form
  $df.Text = "AI PICO â€” Disclaimer"
  $df.Size = New-Object System.Drawing.Size(560, 490)
  $df.StartPosition = "CenterScreen"
  $df.FormBorderStyle = "FixedDialog"
  $df.MaximizeBox = $false
  $lbl = New-Object System.Windows.Forms.Label
  $lbl.Text = @"
AI PICO â€” Clinical Question Assistant
Created by Dr Raouf Roshdy  (c) 2026 â€” All rights reserved

IMPORTANT DISCLAIMER

1. For EDUCATIONAL and ACADEMIC RESEARCH purposes only.
2. NOT a medical device; not certified for clinical or patient-care decisions.
3. AI-generated content may contain errors or outdated information.
4. Always verify questions, references and evidence against original sources.
5. Do NOT enter patient-identifiable data.
6. Provided 'as is' without warranty; the author accepts no liability.

Click 'I Accept' to continue installation.
"@
  $lbl.Location = New-Object System.Drawing.Point(16, 12)
  $lbl.Size = New-Object System.Drawing.Size(510, 360)
  $lbl.Font = New-Object System.Drawing.Font("Segoe UI", 10)
  $df.Controls.Add($lbl)
  $accept = New-Object System.Windows.Forms.Button
  $accept.Text = "I Accept"
  $accept.Location = New-Object System.Drawing.Point(330, 400)
  $accept.Size = New-Object System.Drawing.Size(110, 36)
  $df.Controls.Add($accept)
  $decline = New-Object System.Windows.Forms.Button
  $decline.Text = "Decline & Exit"
  $decline.Location = New-Object System.Drawing.Point(110, 400)
  $decline.Size = New-Object System.Drawing.Size(110, 36)
  $df.Controls.Add($decline)
  $decline.Add_Click({ $df.Close() })
  $accept.Add_Click({ $df.Tag = "ok"; $df.Close() })
  $df.ShowDialog() | Out-Null
  if ($df.Tag -ne "ok") { exit 0 }
  "Accepted $(Get-Date -Format 'yyyy-MM-dd HH:mm')" | Out-File $DisclaimerFile -Encoding utf8
}

# ---------- UI ----------
$form = New-Object System.Windows.Forms.Form
$form.Text = "AI PICO â€” Setup"
$form.Size = New-Object System.Drawing.Size(560, 310)
$form.StartPosition = "CenterScreen"
$form.FormBorderStyle = "FixedDialog"
$form.MaximizeBox = $false

$title = New-Object System.Windows.Forms.Label
$title.Text = "AI PICO â€” Clinical Question Assistant"
$title.Font = New-Object System.Drawing.Font("Segoe UI", 14, [System.Drawing.FontStyle]::Bold)
$title.ForeColor = [System.Drawing.Color]::FromArgb(15,107,107)
$title.Location = New-Object System.Drawing.Point(16, 12)
$title.Size = New-Object System.Drawing.Size(510, 30)
$form.Controls.Add($title)

$subtitle = New-Object System.Windows.Forms.Label
$subtitle.Text = "Created by Dr Raouf Roshdy (c) 2026"
$subtitle.Font = New-Object System.Drawing.Font("Segoe UI", 9, [System.Drawing.FontStyle]::Italic)
$subtitle.ForeColor = [System.Drawing.Color]::Gray
$subtitle.Location = New-Object System.Drawing.Point(16, 44)
$subtitle.Size = New-Object System.Drawing.Size(510, 20)
$form.Controls.Add($subtitle)

$status = New-Object System.Windows.Forms.Label
$status.Text = "Preparingâ€¦"
$status.Location = New-Object System.Drawing.Point(16, 88)
$status.Size = New-Object System.Drawing.Size(510, 24)
$form.Controls.Add($status)

$bar = New-Object System.Windows.Forms.ProgressBar
$bar.Location = New-Object System.Drawing.Point(16, 118)
$bar.Size = New-Object System.Drawing.Size(510, 22)
$form.Controls.Add($bar)

$details = New-Object System.Windows.Forms.TextBox
$details.Multiline = $true; $details.ReadOnly = $true; $details.ScrollBars = "Vertical"
$details.Font = New-Object System.Drawing.Font("Consolas", 8.5)
$details.Location = New-Object System.Drawing.Point(16, 152)
$details.Size = New-Object System.Drawing.Size(510, 92)
$form.Controls.Add($details)

$doneBtn = New-Object System.Windows.Forms.Button
$doneBtn.Text = "Launch AI PICO"
$doneBtn.Location = New-Object System.Drawing.Point(404, 252)
$doneBtn.Size = New-Object System.Drawing.Size(122, 34)
$doneBtn.Enabled = $false
$form.Controls.Add($doneBtn)

$logBtn = New-Object System.Windows.Forms.Button
$logBtn.Text = "Open log"
$logBtn.Location = New-Object System.Drawing.Point(16, 252)
$logBtn.Size = New-Object System.Drawing.Size(100, 34)
$logBtn.Add_Click({ if (Test-Path $LogFile) { Start-Process notepad $LogFile } })
$form.Controls.Add($logBtn)

$sync = [hashtable]::Synchronized(@{
  Status = "Startingâ€¦"; Detail = ""; Progress = 2
  Done = $false; Failed = $false; Error = ""
  Launch = $false
})

$doneBtn.Add_Click({
  $sync.Launch = $true
  Start-Process $ServerUrl
  $form.Close()
})

$form.Show()
$form.Refresh()

# ---------- Background installer runspace ----------
$scriptBlock = {
  param($sync, $AppDir, $LogFile, $sourceB64, $Port)
  function Up($s,$p,$d){ $sync.Status=$s; $sync.Progress=$p; if($d){$sync.Detail=$d} }
  function Log($m){ try { "$(Get-Date -Format 'HH:mm:ss') | $m" | Out-File $LogFile -Append -Encoding utf8 } catch {} }
  try {
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    Log "===== setup started ====="

    Up "Checking Node.jsâ€¦" 5 ""
    $node = $null
    $cmd = Get-Command node.exe -ErrorAction SilentlyContinue
    if ($cmd) { $node = $cmd.Source }
    if (-not $node) {
      foreach ($p in @("$env:ProgramFiles\nodejs\node.exe", "${env:ProgramFiles(x86)}\nodejs\node.exe", "$env:LOCALAPPDATA\Programs\nodejs\node.exe")) {
        if (Test-Path $p) { $node = $p; break }
      }
    }
    if (-not $node) {
      Up "Installing Node.js (one-time)â€¦" 10 "Downloading from nodejs.orgâ€¦"
      $installer = "$env:TEMP\node-installer.msi"
      Invoke-WebRequest -Uri "https://nodejs.org/dist/v20.11.1/node-v20.11.1-x64.msi" -OutFile $installer -UseBasicParsing
      Start-Process msiexec.exe -ArgumentList "/i `"$installer`" /qn" -Wait
      $env:Path = [Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [Environment]::GetEnvironmentVariable("Path","User")
      $cmd = Get-Command node.exe -ErrorAction SilentlyContinue
      if ($cmd) { $node = $cmd.Source } else { $node = "$env:ProgramFiles\nodejs\node.exe" }
      if (-not (Test-Path $node)) { throw "Node.js installation failed. Install from nodejs.org then run setup again." }
    }
    Up "Node.js ready" 20 $node
    $nodeDir = Split-Path $node
    $npm = Join-Path $nodeDir "npm.cmd"

    Up "Extracting application (bundled)â€¦" 30 ""
    $zipPath = "$env:TEMP\aipico-bundled.zip"
    [IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String($sourceB64))
    if (Test-Path $AppDir) { Remove-Item "$AppDir\*" -Recurse -Force -ErrorAction SilentlyContinue }
    $tmp = "$env:TEMP\aipico-extract"
    if (Test-Path $tmp) { Remove-Item $tmp -Recurse -Force }
    Expand-Archive -Path $zipPath -DestinationPath $tmp -Force
    $inner = Get-ChildItem $tmp -Directory | Select-Object -First 1
    Copy-Item "$($inner.FullName)\*" $AppDir -Recurse -Force
    Up "Application extracted" 40 ""

    Set-Location $AppDir
    if (-not (Test-Path $npm)) { throw "npm.cmd not found in $nodeDir" }

    if (-not (Test-Path "$AppDir\node_modules")) {
      Up "Installing dependencies (one-time)â€¦" 50 "npm install running â€” this may take a few minutesâ€¦"
      $out = & $npm install --no-audit --no-fund 2>&1
      Log ($out | Out-String)
      if ($LASTEXITCODE -ne 0) { throw "npm install failed (exit $LASTEXITCODE) â€” see log" }
      Up "Dependencies installed" 68 ""
    } else {
      Up "Dependencies already present" 68 ""
    }

    if (-not (Test-Path "$AppDir\.next")) {
      Up "Building application (one-time)â€¦" 75 "Production build runningâ€¦"
      $out = & $npm run build 2>&1
      Log ($out | Out-String)
      if ($LASTEXITCODE -ne 0) { throw "Build failed (exit $LASTEXITCODE) â€” see log" }
      Up "Build completed" 88 ""
    } else {
      Up "Build already present" 88 ""
    }

    Up "Starting AI PICO serverâ€¦" 92 ""
    $running = $false
    try { $c = Get-NetTCPConnection -LocalPort $Port -ErrorAction SilentlyContinue; if ($c) { $running = $true } } catch {}
    if (-not $running) {
      Start-Process -FilePath $npm -ArgumentList "run","start","--","-p","$Port" -WorkingDirectory $AppDir -WindowStyle Hidden
      for ($i = 0; $i -lt 30; $i++) {
        Start-Sleep -Seconds 2
        try { $r = Invoke-WebRequest -Uri "http://localhost:$Port" -UseBasicParsing -TimeoutSec 3; if ($r.StatusCode -eq 200) { $running = $true; break } } catch {}
      }
      if (-not $running) { throw "Server did not start â€” see log" }
    }
    Up "Ready" 100 "Server running at http://localhost:$Port"
    $sync.Done = $true
  } catch {
    $sync.Failed = $true
    $sync.Error = $_.Exception.Message
    Log "ERROR: $($_.Exception.Message)"
  }
}

$rs = [runspacefactory]::CreateRunspace()
$rs.Open()
$rs.SessionStateProxy.SetVariable("sync", $sync)
$rs.SessionStateProxy.SetVariable("AppDir", $AppDir)
$rs.SessionStateProxy.SetVariable("LogFile", $LogFile)
$rs.SessionStateProxy.SetVariable("sourceB64", $SourceB64)
$rs.SessionStateProxy.SetVariable("Port", $Port)
$ps = [powershell]::Create()
$ps.Runspace = $rs
$ps.AddScript($scriptBlock) | Out-Null
$handle = $ps.BeginInvoke()

# ---------- UI timer polls background progress ----------
$timer = New-Object System.Windows.Forms.Timer
$timer.Interval = 400
$timer.Add_Tick({
  $status.Text = $sync.Status
  $bar.Value = [Math]::Min(100, $sync.Progress)
  if ($sync.Detail) { $details.AppendText("$($sync.Detail)`r`n"); $sync.Detail = "" }
  if ($sync.Done -and -not $doneBtn.Enabled) {
    $status.Text = "âœ” Setup complete! Click Launch AI PICO"
    $status.ForeColor = [System.Drawing.Color]::FromArgb(21,128,61)
    $doneBtn.Enabled = $true
    $doneBtn.BackColor = [System.Drawing.Color]::FromArgb(15,107,107)
    $doneBtn.ForeColor = [System.Drawing.Color]::White
    Start-Process $ServerUrl
  }
  if ($sync.Failed -and $status.ForeColor -ne [System.Drawing.Color]::Firebrick) {
    $status.Text = "âœ– Setup problem"
    $status.ForeColor = [System.Drawing.Color]::Firebrick
    $details.AppendText("ERROR: $($sync.Error)`r`n")
  }
  [System.Windows.Forms.Application]::DoEvents()
})
$timer.Start()

[System.Windows.Forms.Application]::Run($form)
$timer.Stop()
try { $ps.Stop(); $rs.Close() } catch {}

